import { IngestionModel } from '@514labs/moose-lib';

/**
 * User Activity Event data model
 * Represents user interactions with the platform
 */
export interface UserActivityEvent extends IngestionModel {
  eventId: string;
  eventTs: string;
  userId: string;
  action: string;
  durationMs?: number; // Optional field for nullable durations
}

