const fs = require('fs');

// Read the CSV data
const csvData = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf8');
const lines = csvData.trim().split('\n');
const headers = lines[0].split(',');

console.log('Headers:', headers);

// Convert CSV to JSON objects
const events = [];
for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',');

    const event = {
        eventId: values[0],
        eventTs: new Date(values[1]).toISOString(),
        userId: values[2],
        action: values[3],
        durationMs: values[4] === '' || values[4] === '0' ? undefined : parseInt(values[4])
    };

    events.push(event);
}

console.log('Sample event:', JSON.stringify(events[0], null, 2));
console.log(`Total events to load: ${events.length}`);

// Load events one by one via POST to the ingestion API
async function loadEvents() {
    for (let i = 0; i < events.length; i++) {
        const event = events[i];

        try {
            const response = await fetch('http://localhost:4000/ingest/UserActivityEvent', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(event)
            });

            if (response.ok) {
                console.log(`✓ Loaded event ${i + 1}/${events.length}: ${event.eventId}`);
            } else {
                console.error(`✗ Failed to load event ${event.eventId}:`, response.status, await response.text());
            }
        } catch (error) {
            console.error(`✗ Error loading event ${event.eventId}:`, error.message);
        }
    }
    console.log('Data loading complete!');
}

loadEvents();

