import { MaterializedView, sql } from '@514labs/moose-lib';
import { UserActivityEvent } from '../ingest/userActivityEvent';

/**
 * Daily User Summary View
 * Aggregates user activity events by user and day
 */
export interface DailyUserSummary {
  userId: string;
  day: Date;
  eventCount: number;
  totalDuration: number;
}

export const DailyUserSummaryView = new MaterializedView<DailyUserSummary>('DailyUserSummary', {
  sourceTable: 'UserActivityEvent',
  columns: ['userId', 'day', 'eventCount', 'totalDuration'],
  query: sql`
    SELECT
      userId,
      toDate(eventTs) as day,
      count(*) as eventCount,
      sum(coalesce(durationMs, 0)) as totalDuration
    FROM UserActivityEvent
    GROUP BY userId, toDate(eventTs)
    ORDER BY userId, day
  `
});

