### TypeScript Materialized View for Aggregated Tables

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/olap/model-materialized-view.mdx

Defines a materialized view in TypeScript for an AggregatingMergeTree table, using stateful aggregation functions.

```typescript
import { MaterializedView, ClickHouseEngines, Aggregated, sql } from "@514labs/moose-lib";

interface MetricsById {
  id: string;
  avg_rating: number & Aggregated<"avg", [number]>;
  total_reviews: number & Aggregated<"sum", [number]>;
}

const aggStmt = sql.statement`
  SELECT
    ${reviews.columns.id} AS id,
    avgState(${reviews.columns.rating}) AS avg_rating,
    countState(${reviews.columns.id})   AS total_reviews
  FROM ${reviews}
  GROUP BY ${reviews.columns.id}
`;

const mv = new MaterializedView<MetricsById>({
  selectStatement: aggStmt,
  selectTables: [reviews],
  targetTable: {
    name: "metrics_by_id",
    engine: ClickHouseEngines.AggregatingMergeTree,
    orderByFields: ["id"],
  },
  materializedViewName: "mv_metrics_by_id",
});
```

--------------------------------

### Implement Materialized View Rollup

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/engines/aggregating-merge-tree.mdx

Define source and target tables with aggregation logic to pre-calculate metrics at insert time.

```typescript
import { 
  OlapTable, 
  MaterializedView,
  ClickHouseEngines,
  UInt64,
  SimpleAggregated,
  DateTime,
  sql
} from "@514labs/moose-lib";

// Source: raw events
interface PageView {
  timestamp: DateTime;
  user_id: string;
  page: string;
  duration_ms: number;
}

const pageViews = new OlapTable<PageView>("page_views", {
  orderByFields: ["timestamp", "user_id"],
});

// Target: daily aggregates
interface DailyPageStats {
  date: DateTime;
  user_id: string;
  view_count: UInt64 & SimpleAggregated<"sum", UInt64>;
  total_duration: number & SimpleAggregated<"sum", number>;
  max_duration: number & SimpleAggregated<"max", number>;
}

const targetTable = new OlapTable<DailyPageStats>("daily_page_stats", {
  engine: ClickHouseEngines.AggregatingMergeTree,
  orderByFields: ["date", "user_id"],
});

const mv = new MaterializedView<DailyPageStats>({
  materializedViewName: "mv_daily_page_stats",
  selectTables: [pageViews],
  targetTable: targetTable,
  selectStatement: sql.statement`
    SELECT
      toStartOfDay(${pageViews.columns.timestamp}) AS date,
      ${pageViews.columns.user_id}                AS user_id,
      count()                                     AS view_count,
      sum(${pageViews.columns.duration_ms})       AS total_duration,
      max(${pageViews.columns.duration_ms})       AS max_duration
    FROM ${pageViews}
    GROUP BY date, user_id
  `,
});
```

```python
from moose_lib import (
    OlapTable, 
    OlapConfig, 
    MaterializedView,
    MaterializedViewOptions,
    AggregatingMergeTreeEngine,
    simple_aggregated,
)
from pydantic import BaseModel
from datetime import datetime

# Source: raw events
class PageView(BaseModel):
    timestamp: datetime
    user_id: str
    page: str
    duration_ms: int

# Target: daily aggregates
class DailyPageStats(BaseModel):
    date: datetime
    user_id: str
    view_count: simple_aggregated('sum', int)
    total_duration: simple_aggregated('sum', int)
    max_duration: simple_aggregated('max', int)

page_views = OlapTable[PageView]("page_views", OlapConfig(
    order_by_fields=["timestamp", "user_id"]
))

daily_stats = OlapTable[DailyPageStats]("daily_page_stats", OlapConfig(
    engine=AggregatingMergeTreeEngine(),
    order_by_fields=["date", "user_id"]
))

rollup_view = MaterializedView[DailyPageStats](
    MaterializedViewOptions(
        materialized_view_name="mv_daily_page_stats",
        select_tables=[page_views],
        select_statement="""
            SELECT
                toStartOfDay(timestamp) AS date,
                user_id,
                count()                AS view_count,
                sum(duration_ms)       AS total_duration,
                max(duration_ms)       AS max_duration
            FROM {page_views}
            GROUP BY date, user_id
        """,
    ),
    target_table=daily_stats,
)
```

